post.description:
Apply a compatibility policy to a manifest diff.

Body: {
    "policy_id": "..." or "preset": "strict",
    "compare_to": "..."  // optional — defaults to parent
}

x-codeSamples.source:
import decimalai

# Auto-instrumentation (recommended)
decimalai.init(api_key="dai_sk_...", openai_agents=True)

# Or manual tracing with decorator
@decimalai.trace(agent_name="my-agent")
def run_agent(query: str) -> str:
    return llm.invoke(query)

run_agent("What is the weather?")

patch.description:
Set a manual compatibility override for a trace.

Body: {
    "target_manifest_id": "...",  // required — which manifest this override applies to
    "override_verdict": "keep" | "repair" | "replay" | "drop" | null  // null clears the override
}

Flat-trace fallback (no target manifest): {
    "compat_status": "keep" | "repair" | "replay" | "drop"
}

post.description:
